using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;

// ──────────────────────────────────────────────────────────────────────
// EF Core 9 Cosmos DB breaking changes — required fixes for existing data
// ──────────────────────────────────────────────────────────────────────

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change #1: Default discriminator property renamed from
        // "Discriminator" to "$type". Existing documents use "Discriminator",
        // so we must explicitly preserve the old name.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Breaking change #2: The id property no longer includes the
        // discriminator value (was "Session|123", now just "123").
        // Existing documents have the old compound format — preserve it.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

// ──────────────────────────────────────────────────────────────────────
// Breaking change #3: Sync I/O on the Cosmos DB provider now throws.
// All synchronous calls must be converted to async equivalents.
// ──────────────────────────────────────────────────────────────────────

class CosmosQueryService
{
    private readonly CosmosDbContext _db;

    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (throws in EF Core 9):
    //   var sessions = _db.Sessions.Where(s => s.Name == name).ToList();
    //   _db.Sessions.Add(new Session { ... });
    //   _db.SaveChanges();

    // AFTER — use async equivalents:
    public async Task<List<Session>> GetSessionsAsync(string name)
    {
        return await _db.Sessions
            .Where(s => s.Name == name)
            .ToListAsync();
    }

    public async Task AddSessionAsync(Session session)
    {
        _db.Sessions.Add(session);
        await _db.SaveChangesAsync();
    }
}

